
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_pbe4_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_pbe4", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([8.022835033358916e+01, 7.835690695140566e+01, 7.586478421500460e+01, 7.264500336201972e+01, 6.863384976355930e+01, 6.378688946917843e+01, 5.783197858008180e+01, 4.953765262048768e+01, 3.622455352405575e+01, 1.838498816729901e+01, 7.026162037649052e+00, 2.292424641375347e+00, 1.452759489826679e+00, 1.458237925102791e+00, 1.052921427128139e+00, 2.828916319164569e-01, 8.742830748152778e-04, -3.173582778696008e-03, -1.667016513037258e-04, -2.103463037115581e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


